package com.jbrempresa.backend.entity;
import java.time.LocalDateTime; import com.fasterxml.jackson.annotation.JsonFormat; import jakarta.persistence.*;
@Entity @Table(name="contactos_canal") public class ContactoCanal {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="coc_id") private Long cocId; @Column(name="emp_id",nullable=false) private Long empId; @Column(name="coc_can",nullable=false,length=20) private String cocCan; @Column(name="coc_ide",nullable=false,length=200) private String cocIde; @Column(name="coc_usu_mov",nullable=false,length=50) private String cocUsuMov; @JsonFormat(pattern="dd/MM/yyyy HH:mm:ss") @Column(name="coc_fec_mov",nullable=false) private LocalDateTime cocFecMov; @Column(name="coc_act",nullable=false) private Boolean cocAct;
 public Long getCocId(){return cocId;} public void setCocId(Long v){cocId=v;} public Long getEmpId(){return empId;} public void setEmpId(Long v){empId=v;} public String getCocCan(){return cocCan;} public void setCocCan(String v){cocCan=v;} public String getCocIde(){return cocIde;} public void setCocIde(String v){cocIde=v;} public String getCocUsuMov(){return cocUsuMov;} public void setCocUsuMov(String v){cocUsuMov=v;} public LocalDateTime getCocFecMov(){return cocFecMov;} public void setCocFecMov(LocalDateTime v){cocFecMov=v;} public Boolean getCocAct(){return cocAct;} public void setCocAct(Boolean v){cocAct=v;}
}
